INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 9, 'theory', 'Quiz: number algorithms and bits');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 0, 'Why does Euclid''s algorithm take on the order of a logarithm of steps?', '["It tries only prime numbers", "It halves the numbers at every step", "Every two steps the larger number shrinks at least by half", "It uses a table of precomputed remainders"]', 2, 'The remainder is less than half of the dividend, so after two steps the numbers become at least twice smaller. The algorithm is slowest on adjacent Fibonacci numbers, but even there the number of steps is on the order of a logarithm.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 1, 'You need to «divide» by 3 modulo the prime 7. What replaces division by 3?', '["Multiplication by 5, because 3 · 5 ≡ 1 (mod 7)", "Subtracting 3 from the number and taking the remainder", "Multiplication by 7 − 3 = 4", "Dividing by 3 as usual, then taking the remainder"]', 0, 'Dividing modulo a number means multiplying by the inverse element. For 3 modulo 7 it is 5: 15 = 2·7 + 1. The inverse is found with the extended Euclidean algorithm or with the power a^(p−2) by Fermat''s little theorem.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 2, 'Roughly how many multiplications does fast exponentiation need to compute a to the power 10^18?', '["10^18", "About a million, the root of the exponent", "About 18", "About 60, on the order of the binary logarithm of the exponent"]', 3, 'The exponent 10^18 takes about 60 binary digits: that many squarings and at most that many multiplications into the accumulated result. Modulo a number, the values do not grow.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 3, 'Up to what number is it enough to check divisors to be sure that n is prime?', '["Up to n / 2", "Up to the square root of n", "Up to the logarithm of n", "Up to n − 1, otherwise an error is possible"]', 1, 'If n has a divisor d greater than the root, then n / d is also a divisor, and it is less than the root. So every composite n has a divisor no greater than the root.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 9, 4, 'What is x & (x − 1) for x = 44 (binary 101100), and what does it mean?', '["44: the number did not change because it is even", "4: only the low zeros remain", "40: the lowest one was cleared", "45: a one was added on the right"]', 2, 'x − 1 turns the lowest one into zero and the zeros below it into ones, and the bitwise and with x leaves the number without its lowest one: 101000 = 40. A zero result means the number was a power of two.');
